import numpy as np
lbf=np.load('lbf.npy')
def order_path(pix):
    s=set(map(tuple,pix))
    def nb(p):
        out=[]
        for dy in(-1,0,1):
            for dx in(-1,0,1):
                if dy or dx:
                    q=(p[0]+dy,p[1]+dx)
                    if q in s: out.append(q)
        return out
    # BFS to find farthest pair
    import collections
    def bfs(st):
        d={st:0}; dq=collections.deque([st])
        while dq:
            c=dq.popleft()
            for q in nb(c):
                if q not in d: d[q]=d[c]+1; dq.append(q)
        far=max(d,key=lambda k:d[k])
        return far,d
    st=next(iter(s))
    a,_=bfs(st); b,d=bfs(a)
    # reconstruct path from b back to a
    path=[b]; cur=b
    while cur!=a:
        cur=min(nb(cur),key=lambda q: d.get(q,10**9))
        path.append(cur)
    return np.array(path)
def rdp(pts, eps=5):
    if len(pts)<3: return [0,len(pts)-1]
    p0=pts[0].astype(float); p1=pts[-1].astype(float)
    dd=p1-p0; L=np.hypot(dd[0],dd[1])
    if L<1: return [0,len(pts)-1]
    v=pts-p0
    dist=np.abs(v[:,0]*dd[1]-v[:,1]*dd[0])/L
    i=int(np.argmax(dist))
    if dist[i]>eps:
        return rdp(pts[:i+1],eps)[:-1]+[j+i for j in rdp(pts[i:],eps)]
    return [0,len(pts)-1]
for i in range(1,21):
    pix=np.argwhere(lbf==i)
    if len(pix)<5: continue
    p=order_path(pix)
    idx=rdp(p,4)
    print(i, len(pix), len(p), [(int(p[j][1]),int(p[j][0])) for j in idx])
